"use client";
import { cn } from "@/lib/utils";
import {
  panel as surfacePanel,
  secondary as surfaceSecondary,
  field as surfaceField,
} from "@/lib/takt-surface";

import { useState, useRef } from "react";
import { Search, ArrowDownLeft, Command } from "lucide-react";

export function CommandPalette({
  className,
  commands = ["New project", "Find file", "Settings"],
  onExecute,
}: {
  className?: string;
  commands?: string[];
  onExecute?: (command: string) => void;
}) {
  const dialog = useRef<HTMLDialogElement>(null);
  const [query, setQuery] = useState("");
  const [active, setActive] = useState(0);
  const [last, setLast] = useState("");
  const ordered =
    last && commands.includes(last)
      ? [last, ...commands.filter((c) => c !== last)]
      : commands;
  const filtered = ordered.filter((x) =>
    x.toLocaleLowerCase().includes(query.toLocaleLowerCase()),
  );
  function select(value: string) {
    onExecute?.(value);
    setLast(value);
    dialog.current?.close();
  }
  return (
    <>
      <button
        type="button"
        className={cn(surfacePanel + " flex items-center gap-3", className)}
        onClick={() => {
          setQuery("");
          setActive(0);
          dialog.current?.showModal();
        }}
      >
        <Search size={17} />
        {last || "Command palette"}{" "}
        <Command size={13} aria-hidden className="text-muted-foreground" />
      </button>
      <dialog
        ref={dialog}
        aria-label="Command palette"
        className="fixed inset-0 m-auto max-h-[80dvh] w-80 max-w-[calc(100vw-2rem)] rounded-2xl border bg-popover p-3 text-popover-foreground shadow-xl backdrop:bg-black/40"
      >
        <input
          aria-label="Search commands"
          className={surfaceField}
          placeholder="Find a command"
          value={query}
          onChange={(e) => {
            setQuery(e.target.value);
            setActive(0);
          }}
          onKeyDown={(e) => {
            if (e.nativeEvent.isComposing || e.keyCode === 229) return;
            if (!filtered.length) return;
            if (e.key === "ArrowDown" || e.key === "ArrowUp") {
              e.preventDefault();
              setActive(
                (i) =>
                  (i + (e.key === "ArrowDown" ? 1 : -1) + filtered.length) %
                  filtered.length,
              );
            }
            if (e.key === "Enter" && filtered[active]) {
              e.preventDefault();
              select(filtered[active]);
            }
          }}
        />
        <div className="my-2 grid max-h-[45dvh] gap-0.5 overflow-y-auto">
          {filtered.map((c, i) => (
            <button
              type="button"
              key={c}
              className={
                "flex items-center justify-between rounded-lg px-3 py-2 text-left text-sm hover:bg-muted " +
                (i === active ? "bg-muted font-medium" : "")
              }
              onClick={() => select(c)}
            >
              <span>
                {c}
                {c === last && (
                  <small className="ml-2 text-[9px] font-normal text-muted-foreground">
                    Recent
                  </small>
                )}
              </span>
              {i === active && <ArrowDownLeft size={13} aria-hidden />}
            </button>
          ))}
          {!filtered.length && <span>No matches</span>}
        </div>
        <button
          type="button"
          className={surfaceSecondary}
          onClick={() => dialog.current?.close()}
        >
          Close
        </button>
      </dialog>
    </>
  );
}

// Semantic shadcn colors keep the surfaces usable in a host project's own theme.
export const panel =
  "rounded-2xl border border-foreground/10 bg-card p-4 text-sm text-card-foreground shadow-[0_2px_5px_#0000000a,0_8px_18px_-12px_#0003]";
export const field =
  "min-h-10 min-w-0 w-full rounded-xl border border-foreground/10 bg-muted/70 px-3 text-sm text-foreground outline-none motion-safe:transition-[background-color,box-shadow] focus:bg-background focus:ring-1 focus:ring-foreground/35";
export const action =
  "inline-flex min-h-10 cursor-pointer items-center justify-center gap-2 rounded-xl border border-foreground/10 bg-primary px-3.5 py-2 text-sm font-semibold text-primary-foreground shadow-sm outline-offset-4 motion-safe:transition-[transform,box-shadow] motion-safe:active:translate-y-px motion-safe:active:scale-[.97] disabled:cursor-default disabled:opacity-50";
export const secondary =
  "inline-flex min-h-9 cursor-pointer items-center justify-center gap-1.5 rounded-lg border border-foreground/10 bg-background px-3 text-xs font-medium text-foreground outline-offset-2 hover:bg-muted motion-safe:transition-[transform,background-color] motion-safe:active:scale-[.96] disabled:cursor-default disabled:opacity-45";
